{"content": """"Lightweight MLflow tracking for the episodic training loop.

Unlike the mmengine-based ``MLflowHook`` in sw_ai_detection, the ProtoNet
trainer is a plain PyTorch loop, so this is a small wrapper that manages the
run lifecycle and logs params / per-epoch metrics / artifacts. All MLflow
calls are guarded so a tracking-server hiccup never kills a training run.

Configuration is read from the environment (loaded from ``.env``):
    MLFLOW_TRACKING_URI      e.g. http://192.168.2.1:5000
    MLFLOW_EXPERIMENT_NAME   e.g. uav_few_shot_identification
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

try:  # MLflow is optional at runtime (e.g. offline smoke tests)
    import mlflow
except ImportError:  # pragma: no cover
    mlflow = None  # type: ignore[assignment]


class MLflowRun:
    """Context manager wrapping a single MLflow run for a training job."""

    def __init__(
        self,
        enabled: bool = True,
        run_name: str | None = None,
        experiment_name: str | None = None,
        tracking_uri: str | None = None,
    ) -> None:
        self.enabled = enabled and mlflow is not None
        self.run_name = run_name
        self.tracking_uri = tracking_uri or os.environ.get("MLFLOW_TRACKING_URI")
        self.experiment_name = (
            experiment_name
            or os.environ.get("MLFLOW_EXPERIMENT_NAME")
            or "uav_few_shot_identification"
        )
        self._active = False

    def __enter__(self) -> "MLflowRun":
        if not self.enabled:
            return self
        try:
            if self.tracking_uri:
                mlflow.set_tracking_uri(self.tracking_uri)
            mlflow.set_experiment(self.experiment_name)
            mlflow.start_run(run_name=self.run_name)
            self._active = True
            print(f"MLflow: logging to {self.tracking_uri} / "
                  f"{self.experiment_name} (run={self.run_name})")
        except Exception as e:  # pragma: no cover - network dependent
            print(f"MLflow disabled (start failed): {e}")
            self.enabled = False
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        if self.enabled and self._active:
            try:
                mlflow.end_run(status="FAILED" if exc_type else "FINISHED")
            except Exception:  # pragma: no cover
                pass

    def log_params(self, params: dict[str, Any]) -> None:
        if not (self.enabled and self._active):
            return
        try:
            clean = {
                k: (str(v) if isinstance(v, (list, tuple)) else v)
                for k, v in params.items()
                if v is not None
            }
            mlflow.log_params(clean)
        except Exception as e:  # pragma: no cover
            print(f"MLflow param logging failed: {e}")

    def log_metrics(self, metrics: dict[str, float], step: int | None = None) -> None:
        if not (self.enabled and self._active):
            return
        try:
            mlflow.log_metrics(
                {k: float(v) for k, v in metrics.items()
                 if isinstance(v, (int, float))},
                step=step,
            )
        except Exception as e:  # pragma: no cover
            print(f"MLflow metric logging failed: {e}")

    def set_tags(self, tags: dict[str, Any]) -> None:
        if not (self.enabled and self._active):
            return
        try:
            mlflow.set_tags({k: str(v) for k, v in tags.items()})
        except Exception as e:  # pragma: no cover
            print(f"MLflow tag logging failed: {e}")

    def log_artifact(self, path: str | Path, artifact_path: str | None = None) -> None:
        if not (self.enabled and self._active):
            return
        p = Path(path)
        if not p.exists():
            return
        try:
            mlflow.log_artifact(str(p), artifact_path=artifact_path)
        except Exception as e:  # pragma: no cover
            print(f"MLflow artifact upload failed ({path}): {e}")
